  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer       ecommerce_customers        @relation(fields: [ecommerce_customer_id], references: [id], onDelete: Cascade)
  productVariant ecommerce_product_variants @relation(fields: [ecommerce_product_variant_id], references: [id], onDelete: Cascade)

  @@index([ecommerce_customer_id])
  @@index([ecommerce_product_variant_id])
}

/// Customer reviews and ratings for products. Each review includes a
/// numerical rating (1-5), text comments, and references to both the
/// associated product and the customer who provided the review. Reviews are
/// created when customers submit feedback after purchase and serve as a key
/// input for product recommendations and quality evaluation.
///
/// The table establishes relationships with both ecommerce_products (1:N)
/// and ecommerce_customers (1:N), as a single product can have multiple
/// reviews and a single customer can leave multiple reviews.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_product_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belongs to the product being reviewed. {@link ecommerce_products.id}
  product_id String @db.Uuid

  /// Review was written by this customer. {@link ecommerce_customers.id}
  customer_id String @db.Uuid

  /// Numerical customer rating for the product (1-5). Must be between 1 and 5
  /// per business rules.
  rating Int @db.Integer

  /// Optional text comment from customer describing their experience with the
  /// product.
  comment String?

  /// Timestamp when the review was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the review was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the review was soft-deleted (null means active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  product  ecommerce_products  @relation(fields: [product_id], references: [id], onDelete: Cascade)
  customer ecommerce_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  snapshots ecommerce_product_review_snapshots[]

  @@index([product_id])
  @@index([customer_id])
}

/// Immutable historical snapshots of product review modifications with
