  updated_at DateTime @db.Timestamptz

  /// Timestamp when this snapshot was marked as deleted (for soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  review ecommerce_product_reviews @relation(fields: [ecommerce_product_review_id], references: [id], onDelete: Cascade, map: "ecommerce_product_review_snapshots_ecommerce_product_r_54bee129")

  // spellchecker: ignore-next-line
  @@index([ecommerce_product_review_id], map: "ecommerce_product_review_snapshots_ecommerce_product_r_15563233")
}

