    "session has customer",
    session.customer?.id,
    customerData.id,
  );
  TestValidator.equals(
    "session has ip",
    session.ip,
    customerConnection.headers?.ip?.toString(),
  );
  TestValidator.equals(
    "session has href",
    session.href,
    customerConnection.headers?.href?.toString(),
  );
  TestValidator.equals(
    "session has referrer",
    session.referrer,
    customerConnection.headers?.referrer?.toString(),
