export async function test_api_customer_order_list_recent_date_range(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create customer and authenticate using utility function
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
      display_name: RandomGenerator.name(),
      href: "http://localhost",
      referrer: "http://localhost",
      ip: "127.0.0.1",
    } satisfies IEcommerceCustomer.IJoin,
  });
  // 2. Create test orders within last 7 days
  const now = new Date();
  const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const orderCount = RandomGenerator.pick([2, 3]);
  for (let i = 0; i < orderCount; i++) {
    const orderDate = new Date(
      sevenDaysAgo.getTime() +
        Math.random() * (now.getTime() - sevenDaysAgo.getTime()),
    );
    await api.functional.ecommerce.customer.orders.index(customerConnection, {
      body: {
        order_date: orderDate.toISOString(),
      } satisfies IEcommerceOrder.IRequest,
    });
  }
  // 3. Query orders within the last 7 days
  const from_date = sevenDaysAgo.toISOString();
  const orders = await api.functional.ecommerce.customer.orders.index(
    customerConnection,
    {
      body: {
        from_date: from_date,
      } satisfies IEcommerceOrder.IRequest,
    },
  );
  typia.assert(orders);
  // 4. Verify accurate timestamp filtering
  TestValidator.predicate(
    "should have at least one order",
    orders.data.length > 0,
  );
  for (const order of orders.data) {
    const orderDate = new Date(order.order_date);
    TestValidator.predicate(
      `order date ${order.order_date} should be within last 7 days`,
      orderDate >= sevenDaysAgo,
    );
  }
}

