    id: string & tags.Format<"uuid">,
  ): Promise<IEcommerceOrder> {
    try {
      return await getEcommerceCustomerOrdersId({
        customer,
        id,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

